import os,json,re,subprocess,stat
from pathlib import Path
def call(args):
 try:
  r=subprocess.run(args,capture_output=True,text=True,timeout=9)
  return {'rc':r.returncode,'output':r.stdout.strip()[:5000]}
 except Exception as e:return {'rc':99,'output':type(e).__name__}
def meta(q):
 p=Path(q)
 if p.is_symlink():return {'kind':'symlink','points_within_project':str(p.resolve(strict=False)).startswith('/srv/projects/')}
 if not p.exists():return {'kind':'missing'}
 s=p.stat()
 return {'kind':'directory' if p.is_dir() else 'file','mode':oct(stat.S_IMODE(s.st_mode)),'owner_uid':s.st_uid,'group_gid':s.st_gid,'size_bytes':s.st_size}
res={'environment_metadata':{},'unit_structure':{},'services':{},'external_consumers':{},'private_dirs':{},'access':{}}
for project in ('fadego','pink-iptv'):
 p=Path('/srv/projects')/project
 res['private_dirs'][project]={k:meta(str(p/k)) for k in ('private','private/systemd-env','backend/private','current','backend','deploy','infra')}
paths=('/etc/fadego-staging/app.env','/etc/fadego-staging/send-closed.env','/root/project-secrets/fadego-gmail/oauth.env','/etc/pink-iptv/backend.env','/etc/pink-iptv/secrets.env','/etc/pink-iptv/vpn.env','/srv/projects/fadego/private/systemd-env/app.env','/srv/projects/fadego/private/systemd-env/send-closed.env','/srv/projects/pink-iptv/private/systemd-env/backend.env','/srv/projects/pink-iptv/private/systemd-env/secrets.env','/srv/projects/pink-iptv/private/systemd-env/vpn.env')
for x in paths:res['environment_metadata'][x]=meta(x)
for u in ('fadego-staging','pink-iptv-backend','pink-vpn','lowcost-europa','nginx','postgresql@16-main','pm2-iptvpn-bot','pm2-telegram-robot-leads','ssh'):
 res['services'][u]=call(['systemctl','is-active',u]).get('output')
 if u not in ('fadego-staging','pink-iptv-backend','pink-vpn'):continue
 cat=call(['systemctl','cat',u])
 lines=[l.strip() for l in cat['output'].splitlines()]
 # remove Environment= values because secret content might be inline
 res['unit_structure'][u]={'environment_files':[l for l in lines if l.startswith('EnvironmentFile=')],'workdir':[l for l in lines if l.startswith('WorkingDirectory=')],'exec_files':[l.split(' ',1)[0][:200] for l in lines if l.startswith('ExecStart=') or l.startswith('ExecStartPre=')],'fragment_comments':[l[:200] for l in lines if l.startswith('# /etc/systemd/system/')],'unit_has_inline_environment':any(l.startswith('Environment=') for l in lines)}
for base in ('/etc/systemd/system','/etc/nginx','/etc/cron.d','/usr/local/bin','/usr/local/sbin'):
 p=Path(base);refs=[]
 if not p.is_dir():continue
 for cur,ds,fs in os.walk(p):
  if len(Path(cur).relative_to(p).parts)>3:ds[:]=[];continue
  for f in fs:
   q=Path(cur)/f
   try:
    if not q.is_file() or q.stat().st_size>300000:continue
    v=q.read_text(errors='replace')
    found=sorted(set(re.findall(r'/etc/(?:fadego-staging|pink-iptv)/[A-Za-z0-9._/-]+',v)))
    if found:refs.append({'file':str(q),'references':found})
   except Exception:pass
 res['external_consumers'][base]=refs[:40]
res['access']={'euid':os.geteuid()}
print(json.dumps(res,separators=(',',':'),ensure_ascii=True))
